// src/pages/staff/admin/types.ts
async function syncPublicSummary(teams = [], events = [], overrideStudentCount, overrideResults) {
	const { db } = getFirebaseState();
	if (!db) return;
	try {
		let studentCount = overrideStudentCount;
		if (typeof studentCount !== "number") studentCount = (await getDocs(collection(db, "students"))).size;
		let pubResults = overrideResults;
		if (!pubResults) pubResults = (await getDocs(query(collection(db, "results"), where("status", "==", "published")))).docs.map((d) => ({
			id: d.id,
			...d.data()
		}));
		else pubResults = pubResults.filter((r) => !r.status || r.status === "published");
		const teamTotals = {};
		teams.forEach((t) => {
			teamTotals[t] = 0;
		});
		buildTeamScoreLedger(pubResults, (winnerId, _type, res) => res?.winnerDetails?.[winnerId]?.team || "", events).forEach((item) => {
			teamTotals[item.team] = (teamTotals[item.team] || 0) + Number(item.points || 0);
		});
		await setDoc(doc(db, "settings", "public_summary"), {
			studentCount,
			publishedCount: pubResults.length,
			teamScores: teamTotals,
			updatedAt: Date.now()
		}, { merge: true });
		invalidateCache("doc:settings/public_summary");
	} catch (err) {
		console.warn("syncPublicSummary warning:", err);
	}
}
